-- ---------- non-destructive enrichment match ----------
-- Link each prospect to the existing customer whose truncated name_key is the
-- LONGEST (most specific) prefix of the prospect's normalized name. 'strong'
-- when the whole normalized key matches, else 'possible'. Only prospect_
-- companies is updated.
with m as (
  select distinct on (pc.id)
    pc.id  as pid,
    c.id   as cid,
    case
      when pc.company_key = lower(regexp_replace(c.name_key, '[^A-Za-z0-9]', '', 'g'))
      then 'strong' else 'possible'
    end as conf
  from public.prospect_companies pc
  join public.customers c
    on length(regexp_replace(c.name_key, '[^A-Za-z0-9]', '', 'g')) >= 8
   and pc.company_key like lower(regexp_replace(c.name_key, '[^A-Za-z0-9]', '', 'g')) || '%'
  order by pc.id, length(regexp_replace(c.name_key, '[^A-Za-z0-9]', '', 'g')) desc
)
update public.prospect_companies pc
set matched_customer_id = m.cid,
    match_confidence    = m.conf
from m
where pc.id = m.pid;
